import { FIELDS,LABELS,latest,submissionDifferences } from './model.js';
import { companyQuestionProjection,questionAnswerToken,questionSummary } from './question-tracker.js';
import { candidateJobProjection,submissionJob } from './job-settings.js';
import { jobDescriptionView,jobDiffView } from './job-views.js';
import { publicAnswerView } from './question-views.js';
const clone=value=>JSON.parse(JSON.stringify(value));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DECISIONS={wait:'回答を待つ',proceed:'この内容で話を進める',pause:'今は進めない'};
const JOB_RESPONSES={continue:'今の経験で進む',add:'経験を追加する',question:'質問する'};
function publicSubmission(entry){return entry?{version:entry.version,submittedAt:entry.submittedAt,candidateConfirmed:entry.candidateConfirmed,scenario:entry.scenario,sceneId:entry.sceneId,content:Object.fromEntries(FIELDS.map(k=>[k,entry.content[k]]))}:null;}
function publicJob(job){if(!job)return null;return {jobId:job.jobId,version:job.version,publishedAt:job.publishedAt,legacy:job.legacy===true,legacyScenario:job.legacyScenario,content:{...Object.fromEntries(['title','nextStep','contact','changeReason','followupQuestion'].map(k=>[k,job.content[k]])),scenes:job.content.scenes.map(s=>({id:s.id,title:s.title,description:s.description}))}};}

// This projection is the same for both roles. Never pass a company editor to the view.
export function preparationProjection(state){
 const newest=latest(state),sent=state.proposals.at(-1);
 const proposal=sent?{id:sent.id,sequence:sent.sequence,createdAt:sent.createdAt,response:sent.response,agenda:{sourceVersion:sent.agenda.sourceVersion,focus:sent.agenda.focus,confirmNext:sent.agenda.confirmNext,candidateQuestion:sent.agenda.candidateQuestion}}:null;
 const reference=proposal?state.submissions.find(s=>s.version===proposal.agenda.sourceVersion):newest;
 const referenceJob=reference?publicJob(submissionJob(state,reference.version)):null,currentJob=publicJob(candidateJobProjection(state));
 const changedSubmission=!!proposal&&proposal.agenda.sourceVersion!==newest?.version;
 const changedQuestions=!!proposal&&proposal.agenda.candidateQuestion!==questionSummary(state);
 const changedJob=!!referenceJob&&referenceJob.version!==currentJob.version;
 const preference=state.decision&&Object.hasOwn(DECISIONS,state.decision.choice)?{choice:state.decision.choice,label:DECISIONS[state.decision.choice],sourceVersion:state.decision.sourceVersion,current:state.decision.sourceVersion===newest?.version&&state.decision.questionAnswerToken===questionAnswerToken(state)}:null;
 const jobResponse=state.jobResponses?.[currentJob.version];
 const questions=companyQuestionProjection(state),questionCounts={unanswered:0,checking:0,discuss_in_meeting:0,answered:0};
 for(const q of questions)questionCounts[q.answer?.status??'unanswered']++;
 return clone({experienceId:state.experienceId,proposal,reference:publicSubmission(reference),referenceIsProposed:!!proposal,latestSubmissionVersion:newest?.version??null,changedSubmission,changedQuestions,changedJob,needsReview:changedSubmission||changedQuestions||changedJob||!!(proposal&&!reference),differences:changedSubmission&&reference&&newest?submissionDifferences(reference,newest):[],questions,questionCounts,referenceJob,currentJob,preference,jobResponse:jobResponse?{choice:jobResponse.choice,label:JOB_RESPONSES[jobResponse.choice],sourceSubmissionVersion:jobResponse.sourceSubmissionVersion}:null});
}
function summaryView(p,{loadedAt=null,memoryOnly=false}={}){
 const stamp=typeof loadedAt==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(loadedAt)?loadedAt:null;
 const version=v=>v===null||v===undefined?'記録なし':'v'+v;
 const sourceJob=p.referenceJob?(p.referenceJob.legacy?'記録なし（旧デモ）':version(p.referenceJob.version)):'記録なし';
 return '<section class="card preparation-summary"><div class="preparation-summary-heading"><h2>会話を始める前の確認</h2><span class="pill '+(p.needsReview?'warning':'quiet')+'">'+(p.needsReview?'要見直し':p.proposal?'提案済み':'未提案')+'</span></div><p>'+(p.proposal?'企業からの提案を表示しています。この表示は本人との合意・面談確定を意味しません。':'企業からの議題提案は、まだありません。本人との合意・面談確定を示すものではありません。')+'</p><dl class="preparation-version-grid"><div><dt>議題が参照する提出版</dt><dd>'+esc(p.proposal?version(p.proposal.agenda.sourceVersion):'未提案')+'</dd></div><div><dt>現在の本人提出版</dt><dd>'+esc(version(p.latestSubmissionVersion))+'</dd></div><div><dt>表示原文の提出時求人版</dt><dd>'+esc(sourceJob)+'</dd></div><div><dt>現公開求人版</dt><dd>'+esc(version(p.currentJob.version))+'</dd></div></dl>'+(p.changedSubmission?'<p class="warning-text">訂正があります。議題の参照版は v'+p.proposal.agenda.sourceVersion+' のままです。現在の提出 v'+p.latestSubmissionVersion+' との照合・見直しが必要です。</p>':'')+'<p class="small">企業の提案理由：記録なし。提案に含まれる確認点は、下の議題欄に原文で示します。</p><div class="preparation-counts">'+[['unanswered','未回答（未公開を含む）'],['checking','確認中'],['discuss_in_meeting','面談で話したい'],['answered','回答あり']].map(([key,label])=>'<span>'+label+' <strong>'+p.questionCounts[key]+'件</strong></span>').join('')+'</div><p class="small">件数は、この経験の共有済み質問の公開状態から数えています。回答本文の意味から解決済みとは判断しません。</p><div class="preparation-hope"><h3>この経験についての次の会話の希望</h3>'+(p.preference?'<span class="pill">'+esc(p.preference.label)+'</span><p class="small">希望の対象として記録された提出版：v'+p.preference.sourceVersion+'。'+(p.preference.current?'選択時に記録した質問・公開回答の状態は現在と同じです。':'選択後に提出・質問・公開回答の状態が更新されています。更新後の希望は未確認で、以前の希望を保持しています。')+'</p>':'<p>希望は記録なし。未選択を承諾や辞退とは扱いません。</p>')+'<p class="small">希望を選んだ時刻：記録なし。本人が実際に閲覧した版：記録なし（閲覧確認は記録していません）。</p><p>この経験についての次の会話の希望であり、応募全体の辞退ではありません。</p><p class="small">回答を待つことは辞退ではありません。今は進めない場合も回答を読んで希望を変えられます。回答や求人更新で希望を自動変更しません。</p>'+(p.jobResponse?'<p class="small">求人更新への任意の選択：'+esc(p.jobResponse.label)+'</p>':'')+'</div><div class="preparation-loaded"><p class="small">'+(memoryOnly?'このタブ内のデータを表示した時刻：':'このブラウザ内のデータを読み込んだ時刻：')+(stamp?'<time datetime="'+esc(stamp)+'">'+esc(stamp.replace('T',' ').replace(/\.\d{3}Z$/,' UTC'))+'</time>':'記録なし')+'。自動通知や常時同期は保証しません。</p><button class="button secondary" data-action="reload-preparation">このブラウザの保存内容を再読込</button></div></section>';
}
function proposalView(p){if(!p.proposal)return '<section class="card"><span class="pill quiet">未提案</span><h2>会話の議題は、まだ提案されていません。</h2><p>会社側の編集中の議題は表示しません。下の提出原文や質問は会話の材料で、合意した議題ではありません。</p></section>';
 const sent=p.proposal,a=sent.agenda;return '<section class="card preparation-agenda"><span class="pill '+(p.needsReview?'warning':'')+'">明示提案 '+sent.sequence+' · 提出 v'+a.sourceVersion+' 参照</span><h2>'+esc(a.focus)+'</h2><p class="small">提案済みの文面です。'+(sent.response==='pending'?'参加の合意は記録されていません。':sent.response==='accepted'?'この提案への承諾が記録されています。':'この提案への見送りが記録されています。')+'</p><h3>この会話で確かめたいこと</h3><p>'+esc(a.confirmNext)+'</p><p class="small">提案に含まれる確認点の原文です。</p><h3>提案時に含まれた候補者の質問</h3><p>'+esc(a.candidateQuestion)+'</p></section>';
}
function reviewView(p){if(!p.needsReview)return '';return '<section class="stale-banner preparation-review"><h2>会話前に要見直し</h2><p>'+[p.changedSubmission?'候補者の訂正後の提出があります。提案が参照した旧原文をそのまま表示しています。':'',p.changedQuestions?'共有された質問が提案時から変わっています。':'',p.changedJob?'求人説明が提出時から更新されています。':'',p.proposal&&!p.reference?'提案が参照した提出原文が見つかりません。':''].filter(Boolean).join(' ')+'</p><p>この画面は議題を更新・再提案しません。両者で変更を確認してください。</p>'+(p.differences.length?'<details open><summary>提案の参照版と最新提出 v'+p.latestSubmissionVersion+' の差分</summary>'+p.differences.map(d=>'<section class="diff"><h3>'+esc(d.label)+'</h3><div><span>提案の参照原文</span><p>'+esc(d.before)+'</p></div><div class="after"><span>最新の提出内容</span><p>'+esc(d.after)+'</p></div></section>').join('')+'</details>':'')+'</section>';}
function referenceView(p){const entry=p.reference;if(!entry)return '<section class="card"><h2>参照する本人提出原文はありません</h2><p>未提出の経験や下書きは、この共通画面に表示しません。</p></section>';return '<section class="card preparation-reference"><span class="pill quiet">本人提出原文 v'+entry.version+'</span><h2>'+(p.referenceIsProposed?'提案が参照した本人の原文':'最新の本人提出原文（議題は未提案）')+'</h2><p class="small">候補者が内容を確認した自己申告です。身元認証や事実確認を示すものではありません。</p><div class="scenario"><span class="eyebrow">提出時に選んだ場面との関係</span><p>'+esc(entry.scenario)+'</p></div>'+FIELDS.map(k=>'<section class="document-section"><h3>'+LABELS[k]+'</h3><p>'+esc(entry.content[k])+'</p></section>').join('')+'</section>';}
function questionsView(p){return '<section class="card preparation-questions"><h2>現在共有されている質問と公開回答</h2><p class="small">この経験の共有済み質問だけを表示します。未公開の回答は含めません。未回答でも進み方は本人が選べます。</p>'+(p.questions.length?p.questions.map(q=>'<article class="question-card"><span class="pill quiet">提出 v'+q.sourceVersion+' の質問</span><h3>'+esc(q.text)+'</h3>'+publicAnswerView(q.answer)+(q.previousAnswer?'<details class="old-answer"><summary>以前の提出・質問版への公開回答</summary><p class="small">現在の質問への回答とは区別して保持しています。</p><blockquote>'+esc(q.previousAnswer.questionText)+'</blockquote>'+publicAnswerView(q.previousAnswer)+'</details>':'')+'</article>').join(''):'<p>この経験から共有された質問はありません。</p>')+'</section>';}
function jobsView(p){return '<section class="card preparation-jobs"><h2>仕事について共有している前提</h2>'+(p.referenceJob?'<details><summary>参照した提出時の求人説明 '+(p.referenceJob.legacy?'（旧デモの保存範囲）':'v'+p.referenceJob.version)+'</summary>'+jobDescriptionView(p.referenceJob)+'</details>':'<p>提出時の求人説明はありません。</p>')+'<details '+(p.changedJob?'open':'')+'><summary>現在の公開求人 v'+p.currentJob.version+'</summary>'+jobDescriptionView(p.currentJob)+'</details>'+(p.changedJob?'<details open><summary>提出時と現在の求人説明の差分</summary>'+jobDiffView(p.referenceJob,p.currentJob)+'</details>':'')+'</section>';}
export function preparationView(state,options={}){const p=preparationProjection(state);return '<section class="page-heading"><span class="eyebrow">同じ公開内容で、会話の準備</span><h1>何を前提に、何を話すか。</h1><p>'+esc(p.experienceId.replace('experience-','経験 '))+' の読み取り専用画面。候補者と会社は同じ内容を確認します。実際の共有リンクや外部送信はありません。</p><div class="actions"><button class="button secondary" data-action="to-candidate">候補者の画面へ戻る</button><button class="button secondary" data-action="to-recruiter">会社の画面へ戻る</button></div></section><div class="preparation-layout">'+summaryView(p,options)+reviewView(p)+proposalView(p)+referenceView(p)+questionsView(p)+jobsView(p)+'</div>';}
